{"path": "stage1.py", "content": """"Stage 1: parse the orders CSV into typed row dictionaries."""

import csv


def parse_orders(path):
    """Read a CSV with header ``id,qty,price`` and return a list of rows.

    Each row is ``{"id": int, "qty": int, "price": int}`` in file order.
    """
    rows = []
    with open(path, newline="", encoding="utf-8") as handle:
        reader = csv.DictReader(handle)
        for record in reader:
            rows.append(
                {
                    "id": int(record["id"]),
                    "qty": int(record["qty"]),
                    "price": int(record["price"]),
                }
            )
    return rows
"}

{"path": "stage2.py", "content": """"Stage 2: drop non-positive quantities, preserving input order."""


def filter_orders(rows):
    """Return the rows whose ``qty`` is greater than zero, in original order."""
    return [row for row in rows if row["qty"] > 0]
"}

{"path": "stage3.py", "content": """"Stage 3: aggregate total quantity per price."""


def total_by_price(rows):
    """Return ``{price: total_qty}``, summing ``qty`` across equal prices."""
    totals = {}
    for row in rows:
        price = row["price"]
        totals[price] = totals.get(price, 0) + row["qty"]
    return totals
"}

{"path": "stage4.py", "content": """"Stage 4: render the totals map as a newline-terminated report."""


def report(totals):
    """Return ``"<price>:<qty>\\n"`` lines sorted by price ascending."""
    lines = ["{}:{}".format(price, totals[price]) for price in sorted(totals)]
    if not lines:
        return ""
    return "\n".join(lines) + "\n"
"}
